// VULNERABLE — input becomes SQL text
var sql = "SELECT * FROM Users WHERE Email = '" + email + "'";
// email = "x' OR '1'='1"       → returns all users
// email = "x'; DROP TABLE Users;--" → extra statement executes

// SAFE — parameterized command
await using var cmd = new SqlCommand(
    "SELECT * FROM Users WHERE Email = @email", connection);
var p = cmd.Parameters.Add("@email", SqlDbType.NVarChar, 254);
p.Value = email;

// SAFE — EF Core LINQ parameterizes for you
var user = await db.Users.FirstOrDefaultAsync(u => u.Email == email);

// SAFE — interpolated raw SQL compiles {email} into a parameter
var rows = await db.Users
    .FromSql($"SELECT * FROM Users WHERE Email = {email}")
    .ToListAsync();

// RISKY — "raw" APIs are only safe with interpolation, not strings
var unsafeRows = await db.Users
    .FromSqlRaw($"SELECT * FROM Users WHERE Email = '{email}'")
    .ToListAsync();

// DYNAMIC IDENTIFIERS — parameters cannot rename columns; whitelist instead
var column = sortBy?.ToLowerInvariant() switch
{
    "name"    => "Name",
    "created" => "CreatedAt",
    _ => throw new ArgumentException("Unsupported sort field")
};
var direction = ascending ? "ASC" : "DESC";  // two fixed values only
var listSql = $"SELECT * FROM Products ORDER BY {column} {direction}";
